async function loadWeather() {
  try {
    let weather = "Loading...";
    const response = await fetch('https://api.weather.com/today');
    const data = await response.json();
    weather = data.condition;
    console.log("Result: ", weather);
  } catch (error) {
    console.error(error);
  }
}

